INSERT INTO universities (
  university_code, name, slug, country, name_zh, name_en, city_zh, city_en,
  country_id, description_zh, description_en, popular, status
)
SELECT
  'LP_UNI_IMPERIAL_COLLEGE_LONDON', '帝国理工学院', 'local-preview-imperial-college-london', 'United Kingdom',
  '帝国理工学院', 'Imperial College London', '伦敦', 'London',
  c.id, NULL, NULL, false, 'PUBLISHED'
FROM countries c WHERE c.code = 'GB'
ON CONFLICT (university_code) DO UPDATE SET
  name = EXCLUDED.name, slug = EXCLUDED.slug, country = EXCLUDED.country,
  name_zh = EXCLUDED.name_zh, name_en = EXCLUDED.name_en,
  city_zh = EXCLUDED.city_zh, city_en = EXCLUDED.city_en,
  country_id = EXCLUDED.country_id, description_zh = EXCLUDED.description_zh,
  description_en = EXCLUDED.description_en, status = 'PUBLISHED', updated_at = CURRENT_TIMESTAMP;

INSERT INTO universities (
  university_code, name, slug, country, name_zh, name_en, city_zh, city_en,
  country_id, description_zh, description_en, popular, status
)
SELECT
  'LP_UNI_UNIVERSITY_OF_OXFORD', '牛津大学', 'local-preview-university-of-oxford', 'United Kingdom',
  '牛津大学', 'University of Oxford', '牛津', 'Oxford',
  c.id, NULL, 'The University of Oxford is a collegiate research university in Oxford, England. There is evidence of teaching as early as 1096, making it the oldest university in the English-speaking world and the world’s second-oldest university in continuous operation. It grew rapidly from 1167, when Henry II prohibited English students from attending the University of Paris. After escalating conflict between students and the Oxford townspeople, some Oxford academics fled northeast to Cambridge, where they established the University of Cambridge in 1209. The two universities share many common features and are jointly referred to as Oxbridge.', false, 'PUBLISHED'
FROM countries c WHERE c.code = 'GB'
ON CONFLICT (university_code) DO UPDATE SET
  name = EXCLUDED.name, slug = EXCLUDED.slug, country = EXCLUDED.country,
  name_zh = EXCLUDED.name_zh, name_en = EXCLUDED.name_en,
  city_zh = EXCLUDED.city_zh, city_en = EXCLUDED.city_en,
  country_id = EXCLUDED.country_id, description_zh = EXCLUDED.description_zh,
  description_en = EXCLUDED.description_en, status = 'PUBLISHED', updated_at = CURRENT_TIMESTAMP;

