DO $$

BEGIN

  IF (SELECT count(*) FROM universities WHERE university_code LIKE 'LP_UNI_%') <> 80 THEN RAISE EXCEPTION 'Preview university count mismatch'; END IF;

  IF (SELECT count(*) FROM programmes WHERE programme_code LIKE 'LP_PROG_%') <> 734 THEN RAISE EXCEPTION 'Preview programme count mismatch'; END IF;

END $$;

COMMIT;



SELECT count(*) AS preview_universities FROM universities WHERE university_code LIKE 'LP_UNI_%';

SELECT count(*) AS preview_programmes FROM programmes WHERE programme_code LIKE 'LP_PROG_%';

SELECT u.name_zh, u.name_en, count(p.id) AS programmes FROM universities u LEFT JOIN programmes p ON p.university_id = u.id AND p.programme_code LIKE 'LP_PROG_%' WHERE u.university_code LIKE 'LP_UNI_%' GROUP BY u.id ORDER BY programmes DESC, u.name_en;
